import { useCallback,useEffect,useState } from "react";
import api from "../../api/axios";

export default function VendorSupportPage(){
 const [items,setItems]=useState([]);const [subject,setSubject]=useState("");const [message,setMessage]=useState("");const [loading,setLoading]=useState(true);const [error,setError]=useState("");const [notice,setNotice]=useState("");
 const load=useCallback(async()=>{setLoading(true);try{const r=await api.get("/support/tickets");if(!r?.data?.success)throw new Error("Unexpected support response.");setItems(r.data.data?.data??[]);}catch(e){setError(e?.response?.data?.message||e?.message||"Unable to load tickets.");}finally{setLoading(false);}},[]);
 useEffect(()=>{void load();},[load]);
 async function submit(e){e.preventDefault();setError("");setNotice("");try{const r=await api.post("/support/tickets",{subject,message,category:"store",priority:"normal"});if(!r?.data?.success)throw new Error("Ticket creation failed.");setSubject("");setMessage("");setNotice("Support ticket submitted.");await load();}catch(e){setError(e?.response?.data?.message||e?.message||"Unable to submit ticket.");}}
 return <div className="container-fluid py-4"><h1 className="h3">Vendor support</h1><p className="text-muted">Contact marketplace support about your store, products or orders.</p>{error?<div className="alert alert-danger">{error}</div>:null}{notice?<div className="alert alert-success">{notice}</div>:null}<div className="row g-4"><div className="col-lg-5"><div className="card border-0 shadow-sm"><div className="card-body"><h2 className="h5">Create support ticket</h2><form onSubmit={submit}><input className="form-control mb-3" value={subject} onChange={e=>setSubject(e.target.value)} placeholder="Subject" maxLength={180} required/><textarea className="form-control mb-3" rows="5" value={message} onChange={e=>setMessage(e.target.value)} placeholder="Describe your issue (at least 10 characters)" minLength={10} required/><button className="btn btn-primary">Submit ticket</button></form></div></div></div><div className="col-lg-7"><div className="card border-0 shadow-sm"><div className="card-body"><h2 className="h5">Your tickets</h2>{loading?<p>Loading…</p>:items.length===0?<p className="text-muted">No support tickets yet.</p>:items.map(t=><div key={t.id} className="border-bottom py-3"><div className="d-flex justify-content-between"><strong>{t.number}</strong><span className="badge text-bg-secondary">{t.status}</span></div><div>{t.subject}</div><small className="text-muted">{new Date(t.created_at).toLocaleString()}</small></div>)}</div></div></div></div></div>;
}
